package com.micro.gameportal

import kotlin.random.Random

/**
 * Pure Lights Out logic on an N x N board. Toggling a light also toggles its
 * four neighbours. Puzzles are generated by applying random toggles to the
 * all-off (solved) board, so they are always solvable.
 */
class LightsOut(
    val size: Int = 5,
    seed: Long = System.nanoTime(),
) {
    companion object {
        fun cells(size: Int) = size * size
    }

    var lights = BooleanArray(cells(size))
        private set
    var moves = 0
        private set
    var isSolved = true
        private set

    private var random = Random(seed)

    init {
        generate()
    }

    fun newGame(seed: Long = System.nanoTime()) {
        random = Random(seed)
        generate()
    }

    fun restore(savedLights: BooleanArray, savedMoves: Int) {
        require(savedLights.size == lights.size) { "Board must have ${lights.size} cells" }
        lights = savedLights.copyOf()
        moves = savedMoves
        isSolved = lights.none { it }
    }

    /** Toggles the light at [index] and its orthogonal neighbours. */
    fun tap(index: Int): Boolean {
        if (index !in lights.indices) return false
        toggle(index)
        val row = index / size
        val col = index % size
        if (row > 0) toggle(index - size)
        if (row < size - 1) toggle(index + size)
        if (col > 0) toggle(index - 1)
        if (col < size - 1) toggle(index + 1)
        moves++
        isSolved = lights.none { it }
        return true
    }

    private fun toggle(index: Int) {
        lights[index] = !lights[index]
    }

    private fun generate() {
        do {
            lights = BooleanArray(lights.size)
            repeat(size + 2) {
                tapInternal(lights.indices.random(random))
            }
        } while (lights.none { it })
        moves = 0
        isSolved = false
    }

    /** Toggles without counting moves or checking solved (generation only). */
    private fun tapInternal(index: Int) {
        toggle(index)
        val row = index / size
        val col = index % size
        if (row > 0) toggle(index - size)
        if (row < size - 1) toggle(index + size)
        if (col > 0) toggle(index - 1)
        if (col < size - 1) toggle(index + 1)
    }
}
